php -r '$dsn=getenv("EL_DESTINATIONS_DSN");$config=["dsn"=>$dsn,"db_user"=>null,"db_password"=>null,"app_key"=>bin2hex(random_bytes(32)),"admin_user"=>"localadmin","admin_password_hash"=>password_hash("DestinosLocal8014!",PASSWORD_DEFAULT),"registration_enabled"=>false,"business_accounts_enabled"=>true,"local_test"=>true,"privacy"=>["operator"=>"Local","contact"=>"","retention"=>"","retention_en"=>""]];file_put_contents(getenv("EL_LOCAL_CONFIG_PATH"),"<?php\nreturn ".var_export($config,true).";\n");chmod(getenv("EL_LOCAL_CONFIG_PATH"),0600);'

